descriptor.templateCss:
.device-overview {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 10px;
  font-family: sans-serif;
}

.section {
  flex: 1;
  padding: 10px;
  border-radius: 8px;
  background-color: #f9f9f9;
  box-shadow: 0 0 4px rgba(0,0,0,0.1);
}

.section img.device-image {
  max-width: 100%;
  height: auto;
  margin-top: 10px;
}

.status.online {
  background-color: #4CAF50;
  color: white;
  padding: 3px 8px;
  border-radius: 10px;
  font-size: 12px;
  margin-top: 4px;
  display: inline-block;
}

.actions button {
  margin-right: 5px;
  padding: 5px;
  font-size: 14px;
}

.tag {
  background-color: #ccc;
  padding: 2px 6px;
  border-radius: 5px;
  font-size: 12px;
}

.tag.active {
  background-color: #4CAF50;
  color: white;
}

.tag.blue {
  background-color: #007bff;
  color: white;
}

